import{_ as r,o,c as s,ag as n}from"./chunks/framework.D9ghT4bC.js";const c=JSON.parse('{"title":"更新日志","description":"","frontmatter":{"title":"更新日志"},"headers":[],"relativePath":"zh/Community/Mods/CoeHarMod/更新日志/index.md","filePath":"zh/Community/Mods/CoeHarMod/更新日志/index.md"}'),l={name:"zh/Community/Mods/CoeHarMod/更新日志/index.md"};function i(a,t,g,e,h,u){return o(),s("div",null,[...t[0]||(t[0]=[n('<h2 id="📌-版本历史" tabindex="-1">📌 版本历史 <a class="header-anchor" href="#📌-版本历史" aria-label="Permalink to &quot;📌 版本历史&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">最新版本</p><p><strong>v3.3.11</strong> - 适配 Unciv 4.21.8.2</p></div><h2 id="v3-3-12-适配-4-21-8-2" tabindex="-1">v3.3.12 - 适配 4.21.8.2 <a class="header-anchor" href="#v3-3-12-适配-4-21-8-2" aria-label="Permalink to &quot;v3.3.12 - 适配 4.21.8.2&quot;">​</a></h2><ul><li>清理模组检查器全部绿色（OK 级）提示：删除 166 处未引用的 <code>Class.*</code> 自定义 tag 声明及空 unique、未注册 unique（如 Aircraft）；删除毛利人登船、机甲无视地形的恒真条件（只能远古开局 / Robotics 必然晚于 Cybernetics）；吸血鬼全地形 1 移动条件真实保留，加对象级压制 unique</li><li>修复模组检查器全部 38 条黄色警告：删除触发未定义事件 VersionNotice 的无效 unique；Mil/Eco/Dip/Gene.Reveal 建筑加官方压制 unique（Reveal/Hide 互斥开关设计）；ModOptions 压制城邦名=首都名的良性翻译碰撞警告（33 条，原版同结构）</li></ul><h2 id="v3-3-11-适配-4-21-8-2" tabindex="-1">v3.3.11 - 适配 4.21.8.2 <a class="header-anchor" href="#v3-3-11-适配-4-21-8-2" aria-label="Permalink to &quot;v3.3.11 - 适配 4.21.8.2&quot;">​</a></h2><h3 id="⚖️-维护费体系重构" tabindex="-1">⚖️ 维护费体系重构 <a class="header-anchor" href="#⚖️-维护费体系重构" aria-label="Permalink to &quot;⚖️ 维护费体系重构&quot;">​</a></h3><ul><li>迁移到文明6式单位维护费体系：废弃按指挥等级分级的逐段维护费 unique，改为 <code>maintenanceCost</code> 字段 + <code>unitMaintenanceBaseCost</code> 全局系数，每单位固定维护费，不再随进度膨胀、无默认免费单位</li><li>清理迁移后冗余的 Comment 与孤儿翻译</li></ul><h3 id="📜-全民动员优化" tabindex="-1">📜 全民动员优化 <a class="header-anchor" href="#📜-全民动员优化" aria-label="Permalink to &quot;📜 全民动员优化&quot;">​</a></h3><ul><li>全民动员补贴：80 条逐单位重复 unique 合并为一条 Countable 表达式 + 单位 tag，大幅精简规则定义</li></ul><h3 id="🤖-lua-系统重构" tabindex="-1">🤖 Lua 系统重构 <a class="header-anchor" href="#🤖-lua-系统重构" aria-label="Permalink to &quot;🤖 Lua 系统重构&quot;">​</a></h3><ul><li>活用 Lua 系统：将军/海军统帅光环（指挥等级决定覆盖时代）与 AI 市政按时代增量解锁改为 Lua 实现，删除原先逐时代/逐条目的 60+ 条 unique</li><li>资源数据表化；Lua 函数改为 PascalCase 命名，消除 LuaLS 诊断</li></ul><h3 id="🧹-清理与流程" tabindex="-1">🧹 清理与流程 <a class="header-anchor" href="#🧹-清理与流程" aria-label="Permalink to &quot;🧹 清理与流程&quot;">​</a></h3><ul><li>清理注释掉的旧规则定义，共删 1700+ 行</li><li>GitHub Action 不再发布 Release，改为任意标签同步核心文件到 main</li><li>删除过时的项目记忆文档与 python 辅助工具；gitignore 忽略 LuaLS 本地生成文件</li></ul><h2 id="v3-3-10-适配-4-19-15" tabindex="-1">v3.3.10 - 适配 4.19.15 <a class="header-anchor" href="#v3-3-10-适配-4-19-15" aria-label="Permalink to &quot;v3.3.10 - 适配 4.19.15&quot;">​</a></h2><ul><li>允许武僧显示在文明百科中</li><li>修复武僧上限异常的问题</li><li>修复神谕所信仰买项目不减反增的错误</li><li>削弱拜占庭重骑兵提供的快乐，由线性增长改为开根增长</li></ul><h2 id="v3-3-9-适配-4-19-12" tabindex="-1">v3.3.9 - 适配 4.19.12 <a class="header-anchor" href="#v3-3-9-适配-4-19-12" aria-label="Permalink to &quot;v3.3.9 - 适配 4.19.12&quot;">​</a></h2><h3 id="🏛️-建筑调整" tabindex="-1">🏛️ 建筑调整 <a class="header-anchor" href="#🏛️-建筑调整" aria-label="Permalink to &quot;🏛️ 建筑调整&quot;">​</a></h3><ul><li><strong>普通建筑涨价效果</strong>：删除所有普通建筑的涨价效果</li><li><strong>区域地标涨价幅度</strong>：区域地标建筑的涨价幅度翻倍</li></ul><h3 id="📜-开局体验优化" tabindex="-1">📜 开局体验优化 <a class="header-anchor" href="#📜-开局体验优化" aria-label="Permalink to &quot;📜 开局体验优化&quot;">​</a></h3><ul><li><strong>政策卡解锁</strong>：新增开局事件自动打开全部政策卡，简化游戏流程</li><li><strong>时代限制</strong>：限制只能从远古时代开始游戏，避免后续时代开局导致的 bug</li><li><strong>总督点数提醒</strong>：新增富余总督点数待使用的事件提醒</li></ul><h3 id="⚖️-快乐系统优化" tabindex="-1">⚖️ 快乐系统优化 <a class="header-anchor" href="#⚖️-快乐系统优化" aria-label="Permalink to &quot;⚖️ 快乐系统优化&quot;">​</a></h3><ul><li>调整快乐加成系统：每一点城均快乐为全国城市+2%全部产出（科技、文化、信仰、产能、金币，不包括食物）</li><li>优化人口增长限制：城均快乐小于-4（小于等于-5）时不再增长人口</li><li>调整叛军触发条件：城均快乐小于-9（小于等于-10）时可能产能叛军</li><li>修复快乐系统负数无效的错误</li></ul><h3 id="🔧-开发工具" tabindex="-1">🔧 开发工具 <a class="header-anchor" href="#🔧-开发工具" aria-label="Permalink to &quot;🔧 开发工具&quot;">​</a></h3><ul><li>完善 GitHub Actions 工作流，确保 main 分支只包含核心文件</li><li>添加核心文件定义模块（白名单机制）</li><li>新增自动发布 Release 功能和本地打包工具</li><li>更新 release.yml 配置</li><li>迁移文档项目，支持数学公式</li></ul><h2 id="v3-3-8-适配-4-19-11" tabindex="-1">v3.3.8 - 适配 4.19.11 <a class="header-anchor" href="#v3-3-8-适配-4-19-11" aria-label="Permalink to &quot;v3.3.8 - 适配 4.19.11&quot;">​</a></h2><h3 id="🎨-文档网站重构" tabindex="-1">🎨 文档网站重构 <a class="header-anchor" href="#🎨-文档网站重构" aria-label="Permalink to &quot;🎨 文档网站重构&quot;">​</a></h3><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" checked="" disabled="" type="checkbox"> 重新组织文档目录结构，分为原版专区、CoeHarMod专区、其他模组专区</li><li class="task-list-item"><input class="task-list-item-checkbox" checked="" disabled="" type="checkbox"> 将文档文件名改为中文，方便中文用户访问</li><li class="task-list-item"><input class="task-list-item-checkbox" checked="" disabled="" type="checkbox"> 更新首页内容，突出 Unciv 中文社区定位</li><li class="task-list-item"><input class="task-list-item-checkbox" checked="" disabled="" type="checkbox"> 更新导航栏和侧边栏，原版专区改为下拉菜单</li><li class="task-list-item"><input class="task-list-item-checkbox" checked="" disabled="" type="checkbox"> 添加众神与国王入门指南文档，包含 18 张配图</li><li class="task-list-item"><input class="task-list-item-checkbox" checked="" disabled="" type="checkbox"> 添加两个 QQ 群链接：Unciv 中文社区群和 CoeHarMod 模组群</li></ul><h3 id="🤖-自动发布功能" tabindex="-1">🤖 自动发布功能 <a class="header-anchor" href="#🤖-自动发布功能" aria-label="Permalink to &quot;🤖 自动发布功能&quot;">​</a></h3><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" checked="" disabled="" type="checkbox"> 新增 GitHub Actions 自动发布 workflow，支持 v.x.x.x 标签触发</li><li class="task-list-item"><input class="task-list-item-checkbox" checked="" disabled="" type="checkbox"> 新增 extract_changelog.py 脚本，自动从更新日志提取对应版本内容</li><li class="task-list-item"><input class="task-list-item-checkbox" checked="" disabled="" type="checkbox"> 新增 build_mod.py 打包工具，自动生成模组安装包</li><li class="task-list-item"><input class="task-list-item-checkbox" checked="" disabled="" type="checkbox"> Release 正文自动从更新日志读取，支持灵活匹配版本标题格式</li></ul><h2 id="v3-3-7-适配-4-19-11" tabindex="-1">v3.3.7 - 适配 4.19.11 <a class="header-anchor" href="#v3-3-7-适配-4-19-11" aria-label="Permalink to &quot;v3.3.7 - 适配 4.19.11&quot;">​</a></h2><h3 id="⛪-宗教信条重做" tabindex="-1">⛪ 宗教信条重做 <a class="header-anchor" href="#⛪-宗教信条重做" aria-label="Permalink to &quot;⛪ 宗教信条重做&quot;">​</a></h3><ul><li><strong>禅修</strong>：每个信教且拥有区域地标的城市+2快乐</li><li><strong>合唱圣歌</strong>：神社+2文，寺庙+4文</li><li><strong>职业道德</strong>：神社+2锤，寺庙+4锤</li><li><strong>宗教社区</strong>：神社+6金，寺庙+12金</li><li><strong>神灵启示</strong>：有人造世界奇观的城市+2科+2文+2金+2鸽</li><li><strong>管理工作</strong>：学院地标+2科，商业区地标+2金</li><li><strong>民间宗教团</strong>：圣地地标+2鸽，剧院地标+2文</li><li><strong>经文</strong>：自然传教速度+100%，研究印刷术后再+100%</li><li><strong>城市守护女神</strong>：没有区域地标的城市修建区域地标时+40%产能</li><li><strong>丰产仪式</strong>：首都+1粮，粮仓+1粮，水渠地标+1快乐</li><li><strong>工匠之神</strong>：进入古典时代后每个基本战略资源地块（马、铁、硝石等，地脉不算）+1锤+1鸽+1金</li><li><strong>牧民之路</strong>：牧场+1金，马厩为所在城市的牧场+1锤</li><li><strong>祈龙仪式</strong>：渔船+3鸽</li><li><strong>月亮女神</strong>：渔船+4金，制图学再+2金</li><li><strong>众神纪念碑</strong>：建造所有奇观时+20%锤</li><li><strong>狩猎女神</strong>：营地+1粮+2金</li><li><strong>宗教偶像</strong>：改良后的奢侈品资源+1金+1鸽，每3个奢侈（包括重复的）+1快乐</li></ul><h3 id="🌱-改良设施调整" tabindex="-1">🌱 改良设施调整 <a class="header-anchor" href="#🌱-改良设施调整" aria-label="Permalink to &quot;🌱 改良设施调整&quot;">​</a></h3><ul><li>位于非丘陵的种植园和营地：额外+1锤</li></ul><h3 id="🏛️-建筑调整-1" tabindex="-1">🏛️ 建筑调整 <a class="header-anchor" href="#🏛️-建筑调整-1" aria-label="Permalink to &quot;🏛️ 建筑调整&quot;">​</a></h3><ul><li><strong>马厩</strong>：造价110锤 → 80锤，与兵营持平；元朝的斡耳朵取消半价</li></ul><h3 id="👥-总督系统调整" tabindex="-1">👥 总督系统调整 <a class="header-anchor" href="#👥-总督系统调整" aria-label="Permalink to &quot;👥 总督系统调整&quot;">​</a></h3><ul><li>必须点完全部前置才能点下一层升级 → 完成任一前置就能点下一层升级</li></ul><h3 id="🌍-国家技能调整" tabindex="-1">🌍 国家技能调整 <a class="header-anchor" href="#🌍-国家技能调整" aria-label="Permalink to &quot;🌍 国家技能调整&quot;">​</a></h3><ul><li><strong>拜占庭</strong>：废弃原有技能，重骑兵单位+n%战斗力，n为快乐/重骑兵数，重骑兵为全国+m快乐，m为此重骑兵所处时代的时代数（重型战车为1，马镫解锁的骑士为3）</li><li><strong>印尼</strong>：学院和圣地获得对浅海和湖泊的+1相邻加成 → 沿海区域产出+50%</li><li><strong>马里</strong>： <ul><li>全国-15%锤 → 全国-5%锤</li><li>市中心依据相邻的沙漠数量获得加成 → 只要相邻沙漠固定提供+2粮+2金+2鸽</li></ul></li></ul><h3 id="📜-政策卡调整" tabindex="-1">📜 政策卡调整 <a class="header-anchor" href="#📜-政策卡调整" aria-label="Permalink to &quot;📜 政策卡调整&quot;">​</a></h3><ul><li>近战加速卡对侦察单位同样生效</li><li>骑兵加速卡对攻城单位同样生效</li><li>边防军：驻军城市+2锤 → 驻军城市+1快乐</li></ul><h3 id="👑-政体调整" tabindex="-1">👑 政体调整 <a class="header-anchor" href="#👑-政体调整" aria-label="Permalink to &quot;👑 政体调整&quot;">​</a></h3><ul><li>专制传承同步独裁统治的效果</li></ul><h3 id="⚔️-单位调整" tabindex="-1">⚔️ 单位调整 <a class="header-anchor" href="#⚔️-单位调整" aria-label="Permalink to &quot;⚔️ 单位调整&quot;">​</a></h3><ul><li>攻城单位攻击船运单位+70%战斗力</li></ul><h3 id="😊-厌战度系统铺垫" tabindex="-1">😊 厌战度系统铺垫 <a class="header-anchor" href="#😊-厌战度系统铺垫" aria-label="Permalink to &quot;😊 厌战度系统铺垫&quot;">​</a></h3><ul><li>每点平均快乐（快乐除以城市数），全国所有城市+5%生产力、科研、文化、金币、信仰值，上下均不封顶</li><li>当平均快乐低于-2时，城市人口增长停止</li><li>当平均快乐低于-4时，可能叛变生成叛军单位</li></ul><h2 id="v3-3-6-适配-4-19-10" tabindex="-1">v3.3.6 - 适配 4.19.10 <a class="header-anchor" href="#v3-3-6-适配-4-19-10" aria-label="Permalink to &quot;v3.3.6 - 适配 4.19.10&quot;">​</a></h2><h3 id="⚖️-调整平衡性" tabindex="-1">⚖️ 调整平衡性 <a class="header-anchor" href="#⚖️-调整平衡性" aria-label="Permalink to &quot;⚖️ 调整平衡性&quot;">​</a></h3><ul><li><strong>水磨</strong>：新增所在城市的<strong>农田</strong>+1锤，无需沿河即可建造</li><li><strong>法国民法典</strong>：提前到<strong>火药</strong>解锁，但解锁<strong>启蒙运动</strong>前部分效果无效</li><li><strong>惧怕拿破仑</strong>：对<strong>法国</strong>单位改为增益，血量低于50时+13%战斗力</li><li><strong>建造者</strong>不消耗劳动力次数砍树</li><li><strong>玛雅</strong>的<strong>天文台</strong>对<strong>种植园</strong>相邻加成：+2 → +1；新增<strong>种植园</strong>每相邻1个<strong>天文台</strong>+1科，解锁<strong>平民教育</strong>科技后额外+1科</li></ul><h3 id="🐛-修bug" tabindex="-1">🐛 修bug <a class="header-anchor" href="#🐛-修bug" aria-label="Permalink to &quot;🐛 修bug&quot;">​</a></h3><ul><li><strong>古老城区</strong>经济政策卡生效范围错误</li></ul><h3 id="📄-新增在线更新日志功能" tabindex="-1">📄 新增在线更新日志功能 <a class="header-anchor" href="#📄-新增在线更新日志功能" aria-label="Permalink to &quot;📄 新增在线更新日志功能&quot;">​</a></h3><h3 id="🔮-新增第五结社" tabindex="-1">🔮 新增第五结社 <a class="header-anchor" href="#🔮-新增第五结社" aria-label="Permalink to &quot;🔮 新增第五结社&quot;">​</a></h3><ul><li><strong>上古维序</strong>：作为占位符，具体内容等待后续更新</li></ul><h2 id="v3-3-5-适配-4-19-9" tabindex="-1">v3.3.5 - 适配 4.19.9 <a class="header-anchor" href="#v3-3-5-适配-4-19-9" aria-label="Permalink to &quot;v3.3.5 - 适配 4.19.9&quot;">​</a></h2><ul><li>回退<strong>联机速</strong>科文需求减少，科技需求变为90%，文化仍然是100%</li><li><strong>奢侈品资源</strong>提供的快乐修改：基础+2快乐，每建立一座新城市额外+2，至多+8，<strong>游戏和娱乐</strong>市政不提供额外快乐</li><li>调整<strong>法兰西</strong></li></ul><h2 id="v3-3-4-适配-4-19-9" tabindex="-1">v3.3.4 - 适配 4.19.9 <a class="header-anchor" href="#v3-3-4-适配-4-19-9" aria-label="Permalink to &quot;v3.3.4 - 适配 4.19.9&quot;">​</a></h2><ul><li>修复<strong>阿玛尼总督</strong>建筑相关的错误</li><li>翻新几乎所有奇观和建筑的贴图</li><li>调整<strong>西班牙灯塔</strong>建筑效果</li></ul><h2 id="v3-3-3-适配-4-19-9" tabindex="-1">v3.3.3 - 适配 4.19.9 <a class="header-anchor" href="#v3-3-3-适配-4-19-9" aria-label="Permalink to &quot;v3.3.3 - 适配 4.19.9&quot;">​</a></h2><ul><li>调整联机速科文需求为原来的80%</li><li>调整<strong>血色契约结社</strong>：<strong>吸血鬼</strong>只能在首都购买，且购买后3t内<strong>移动力</strong>-2<strong>战斗力</strong>-97%</li><li>替换<strong>我就是地主</strong>奇观等等一大批贴图</li></ul><h2 id="v3-3-2-适配-4-19-9" tabindex="-1">v3.3.2 - 适配 4.19.9 <a class="header-anchor" href="#v3-3-2-适配-4-19-9" aria-label="Permalink to &quot;v3.3.2 - 适配 4.19.9&quot;">​</a></h2><h3 id="🐛-修复bug" tabindex="-1">🐛 修复BUG <a class="header-anchor" href="#🐛-修复bug" aria-label="Permalink to &quot;🐛 修复BUG&quot;">​</a></h3><ul><li>删除早就过时的<strong>美利坚专属科技</strong></li><li>为<strong>黄金黎明结社</strong>添加限制条件，避免在未开启结社模式的情况下启用</li><li>删除<strong>奥斯曼</strong>文明百科索引</li><li>万神殿<strong>赫尔墨斯</strong>商路加钱改为<strong>贸易站</strong></li><li>修复不能买<strong>总督建筑</strong>的错误</li></ul><h2 id="v3-3-1-适配-4-19-9" tabindex="-1">v3.3.1 - 适配 4.19.9 <a class="header-anchor" href="#v3-3-1-适配-4-19-9" aria-label="Permalink to &quot;v3.3.1 - 适配 4.19.9&quot;">​</a></h2><h3 id="🎛️-大幅调整政策ui" tabindex="-1">🎛️ 大幅调整政策UI <a class="header-anchor" href="#🎛️-大幅调整政策ui" aria-label="Permalink to &quot;🎛️ 大幅调整政策UI&quot;">​</a></h3><ul><li><strong>通用总督</strong>的升级从建筑整合到政策界面</li></ul><h3 id="👥-大幅调整通用总督技能" tabindex="-1">👥 大幅调整通用总督技能 <a class="header-anchor" href="#👥-大幅调整通用总督技能" aria-label="Permalink to &quot;👥 大幅调整通用总督技能&quot;">​</a></h3><ul><li>总督卸任建筑造价（标准速度下）：30锤 → 50锤</li><li><strong>马格努斯I</strong>：所在城市<strong>森林</strong>、<strong>雨林</strong>和<strong>沼泽</strong>不提供额外产出，所在城市的<strong>保底岗</strong>+1锤，所在城市提供额外2个<strong>保底岗</strong></li><li><strong>马格努斯IIA</strong>：所在城市<strong>工作坊</strong>+2锤，<strong>工厂</strong>+4锤，<strong>发电厂</strong>+7锤，解锁<strong>工业化</strong>后+4<strong>电力</strong></li><li><strong>马格努斯IIB</strong>：所在城市+4住房，人口增长速度+20%，训练<strong>开拓者</strong>不扣除人口</li><li><strong>马格努斯IIIA</strong>：所在城市+20%锤</li><li><strong>马格努斯IIIB</strong>：全国每个<strong>贸易站</strong>+1粮+2锤</li><li><strong>马格努斯IV</strong>：全国每拥有1个<strong>发电厂</strong>所在城市+3锤</li><li><strong>瑞纳I</strong>：全国每个<strong>贸易站</strong>+4金，所在城市新训练的<strong>商人</strong>所有地形只消耗1<strong>移动力</strong></li><li><strong>瑞纳IIA</strong>：所在城市的<strong>港口</strong>与<strong>商业区</strong>地基产出翻倍，所在城市+15%金</li><li><strong>瑞纳IIB</strong>：所在城市未开发地块+3金</li><li><strong>瑞纳III</strong>：+1贸易路线容量，所在城市每人口+2金</li><li><strong>瑞纳IVA</strong>：所在城市用钱买东西花费-50%</li><li><strong>瑞纳IVB</strong>：全球主要文明每有3个<strong>贸易站</strong>全国每个<strong>贸易站</strong>+1科+1文</li><li><strong>阿玛尼I</strong>：所在城市+2粮+2锤，获得1个免费<strong>使者</strong></li><li><strong>阿玛尼IIA</strong>：全球所有城邦获得免费的<strong>远古城墙</strong></li><li><strong>阿玛尼IIB</strong>：解锁相关科技后<strong>基本战略资源</strong>+2</li><li><strong>阿玛尼IIIA</strong>：获得2单位<strong>间谍容量</strong>，获得1个免费的<strong>专业间谍</strong></li><li><strong>阿玛尼IIIB</strong>：每个<strong>市政广场区域建筑</strong>和<strong>外交区区域建筑</strong>+1粮+2锤</li><li><strong>阿玛尼IV</strong>：<strong>影响力点数</strong>获取速率+100%，给城邦钱刷好感效率+100%</li><li><strong>维克多I</strong>：在所在城市市中心的单位<strong>战斗力</strong>+51%</li><li><strong>维克多IIA</strong>：所在城市地块上的我方单位<strong>战斗力</strong>+23%</li><li><strong>维克多IIB</strong>：所在城市训练军队时+25%锤</li><li><strong>维克多IIIA</strong>：所在城市防御和（城炮）攻击时<strong>战斗力</strong>+51%</li><li><strong>维克多IIIB</strong>：所在城市新训练的军队自带10XP</li><li><strong>维克多IV</strong>：所在城市建造<strong>核弹头</strong>和<strong>热核弹头</strong>时+100%锤</li><li><strong>平加拉I</strong>：所在城市+15%科</li><li><strong>平加拉IIA</strong>：所在城市<strong>伟人点数</strong>翻倍</li><li><strong>平加拉IIB</strong>：所在城市每人口+1科</li><li><strong>平加拉IIIA</strong>：所在城市的<strong>图书馆</strong>+3科，<strong>大学</strong>+5科，<strong>研究实验室</strong>+7科</li><li><strong>平加拉IIIB</strong>：每个<strong>贸易站</strong>+1粮+3科</li><li><strong>平加拉IV</strong>：所在城市训练<strong>太空竞赛单位</strong>时+50%锤</li><li><strong>梁I</strong>：所在城市训练<strong>建造者</strong>时+20%锤，新<strong>建造者</strong>+2速</li><li><strong>梁IIA</strong>：所在城市的<strong>冲积平原</strong>和<strong>火山灰</strong>+1锤</li><li><strong>梁IIB</strong>：所在城市的<strong>资源</strong>地块+1粮</li><li><strong>梁IIIA</strong>：允许在所在城市修建<strong>市立公园</strong>，基础+3科+2文+2住房+2快乐，使<strong>卸任梁总督</strong>建筑造价降低到20锤（标准速度下）</li><li><strong>梁IIIB</strong>：所在城市的<strong>资源</strong>地块+1锤</li><li><strong>梁IV</strong>：所在城市+5<strong>住房</strong>，每个<strong>区域地标</strong>+2快乐</li><li><strong>莫克夏I</strong>：所在城市+15%文，每个<strong>区域地标</strong>+2信仰</li><li><strong>莫克夏IIA</strong>：所在城市每人口+1文，自然传教速度+100%</li><li><strong>莫克夏IIB</strong>：若建成圣地则+2<strong>大预言家点数</strong>，全国每个<strong>圣地</strong>在国家面板+2信仰</li><li><strong>莫克夏IIIA</strong>：每个<strong>贸易站</strong>+1粮+2文，所在城市信仰买东西花费-10%</li><li><strong>莫克夏IIIB</strong>：150%富裕的快乐转化为信仰</li><li><strong>莫克夏IV</strong>：建有<strong>圣地</strong>的城市建造<strong>剧院广场区域建筑</strong>时+25%锤，若拥有<strong>莫克夏总督</strong>再+25%</li><li><strong>大维齐尔I</strong>：所在城市训练军队时+25%锤</li><li><strong>大维齐尔II</strong>：所在城市每人口+1科，所有单位攻城时<strong>战斗力</strong>+23%</li><li><strong>大维齐尔III</strong>：所在城市每人口+1文，新训练的单位<strong>移动力</strong>+1</li><li><strong>大维齐尔IV</strong>：所在城市+5住房，+10快乐</li></ul><h3 id="🔧-其他调整" tabindex="-1">🔧 其他调整 <a class="header-anchor" href="#🔧-其他调整" aria-label="Permalink to &quot;🔧 其他调整&quot;">​</a></h3><ul><li>删去<s>首都提供额外2个<strong>保底岗</strong></s></li><li>修改信条<strong>十字军</strong>不生效的错误，重做为无需传教即可在敌国领土+13%力</li><li>重做<strong>朝鲜</strong>技能：每级<strong>总督</strong>升级为所在城市+4%科+4%文 → 有<strong>总督</strong>的城市+8%科，没<strong>总督</strong>的城市-15%科</li><li>修复<strong>马里</strong>用信仰买建筑的花费只和时代有关的错误</li></ul><h2 id="v3-3-0-适配-4-19-9" tabindex="-1">v3.3.0 - 适配 4.19.9 <a class="header-anchor" href="#v3-3-0-适配-4-19-9" aria-label="Permalink to &quot;v3.3.0 - 适配 4.19.9&quot;">​</a></h2><h3 id="⛪-调整万神殿" tabindex="-1">⛪ 调整万神殿 <a class="header-anchor" href="#⛪-调整万神殿" aria-label="Permalink to &quot;⛪ 调整万神殿&quot;">​</a></h3><ul><li><strong>河神</strong>：沿河城市+1文，沿河<strong>圣地</strong>+2快乐+1住房 → 沿河城市+1信仰，沿河<strong>圣地</strong>+1快乐+1住房</li><li><strong>明道之主</strong>：首都+4快乐，所有城市+1锤 → 人口不满-5%，2人口及以下的城+1锤</li><li><strong>恩惠女神</strong>：<strong>种植园</strong>+2粮+1锤+1金 → <strong>种植园</strong>+1粮+2金</li><li><strong>宗教移民</strong>：<strong>政治哲学</strong>送<strong>开拓者</strong>，<strong>开拓者</strong>+1速 → 生产<strong>开拓者</strong>+20%生产力</li><li><strong>丰产仪式</strong>：首都送<strong>粮仓</strong>，<strong>粮仓</strong>+1粮，允许信仰买<strong>粮仓</strong>，免费<strong>建造者</strong> → 首都+1粮，每3人口+1粮</li><li><strong>主神纪念碑</strong>：前两城送<strong>纪念碑</strong>，允许信仰买<strong>纪念碑</strong>，<strong>纪念碑</strong>+10%文 → 首都+1文，每3个<strong>纪念碑</strong>使首都+1文</li><li><strong>节庆女神</strong>：<strong>种植园</strong>+1文+1锤 → +1文</li><li><strong>大地女神</strong>：（只对<strong>印加</strong>）山脉+5信仰 → +1信仰</li><li><strong>山之苗裔</strong>：<strong>学院</strong>和<strong>圣地</strong>对<strong>山脉</strong>+2相邻加成 → 靠山城市+1信仰，允许用信仰在靠山城市买<strong>纪念碑</strong></li><li><strong>雨神</strong>：所有城市+1住房，无水城额外+1住房 → 所有城市+1住房，无水城额外+2住房</li><li><strong>长生天</strong>：<strong>牧场</strong>+1锤，有<strong>圣地</strong>的城市的<strong>牧场</strong>+1文+1信仰 → 有<strong>圣地</strong>的城市的<strong>牧场</strong>+1文+1信仰，建造<strong>马厩</strong>加速25%</li></ul><h3 id="🎛️-大幅调整政策ui-1" tabindex="-1">🎛️ 大幅调整政策UI <a class="header-anchor" href="#🎛️-大幅调整政策ui-1" aria-label="Permalink to &quot;🎛️ 大幅调整政策UI&quot;">​</a></h3><ul><li><strong>秘密结社</strong>从首都建筑整合到政策界面</li><li>合并原来的伟人界面并重新配图</li></ul><h3 id="🔧-其他调整-1" tabindex="-1">🔧 其他调整 <a class="header-anchor" href="#🔧-其他调整-1" aria-label="Permalink to &quot;🔧 其他调整&quot;">​</a></h3><ul><li>修复<strong>耶稣会教育</strong>买建筑固定价格的错误</li></ul><h2 id="v3-2-10-适配-4-19-9" tabindex="-1">v3.2.10 - 适配 4.19.9 <a class="header-anchor" href="#v3-2-10-适配-4-19-9" aria-label="Permalink to &quot;v3.2.10 - 适配 4.19.9&quot;">​</a></h2><h3 id="⚔️-调整攻城相关数值" tabindex="-1">⚔️ 调整攻城相关数值 <a class="header-anchor" href="#⚔️-调整攻城相关数值" aria-label="Permalink to &quot;⚔️ 调整攻城相关数值&quot;">​</a></h3><ul><li>移除<strong>长程陆军</strong>的攻城惩罚：<s><strong>远古</strong>攻城-34%力，<strong>古典</strong>-58%，<strong>中世纪</strong>及以后-96%</s></li><li>提高<strong>攻城类单位</strong>的加力：攻城+51%力，对海+51% → 攻城+104%，对海+70%</li><li>城市基础血量提高：200HP → 400HP</li></ul><h3 id="🌲-调整砍树相关数值" tabindex="-1">🌲 调整砍树相关数值 <a class="header-anchor" href="#🌲-调整砍树相关数值" aria-label="Permalink to &quot;🌲 调整砍树相关数值&quot;">​</a></h3><ul><li>调整收益为固定值（标准速度下）：<strong>森林</strong>+20锤，<strong>雨林</strong>+10粮10锤，<strong>沼泽</strong>+20粮</li><li>砍树时间固定为2回合（标准速度下）</li></ul><h3 id="🎭-重做剧院广场区域建筑" tabindex="-1">🎭 重做<strong>剧院广场区域建筑</strong> <a class="header-anchor" href="#🎭-重做剧院广场区域建筑" aria-label="Permalink to &quot;🎭 重做**剧院广场区域建筑**&quot;">​</a></h3><ul><li><strong>古罗马剧场</strong>：固定+2文 → 每过去一个时代+2文</li><li><strong>艺术博物馆</strong>：固定+4文 → 全球主要文明每存在1个剧院+1文</li><li><strong>考古博物馆</strong>：一次性提供135文 → 使用文化购买单位的成本-3%</li><li><strong>广播中心</strong>：固定+4文，通电额外+6文 → 固定+4文，通电为全国文化+5%</li></ul><h3 id="💎-提高战略资源获取效率" tabindex="-1">💎 提高战略资源获取效率 <a class="header-anchor" href="#💎-提高战略资源获取效率" aria-label="Permalink to &quot;💎 提高战略资源获取效率&quot;">​</a></h3><ul><li><strong>军营区域建筑</strong>提供的战略资源：+1 → +2</li><li>提供<strong>基本战略资源</strong>的军事政策卡：+2 → +4且相关资源获取效率+50%</li></ul><h3 id="🔧-其他调整-2" tabindex="-1">🔧 其他调整 <a class="header-anchor" href="#🔧-其他调整-2" aria-label="Permalink to &quot;🔧 其他调整&quot;">​</a></h3><ul><li>为<strong>武僧</strong>单位的晋升添加前后依赖</li><li>重做<strong>门神</strong>万神殿：所有城市赠送免费的远古城墙，城市防御时+18%力</li><li><strong>桨帆船</strong>可以修建一次<strong>渔船</strong></li><li><strong>矿山</strong>不再允许修建在植被上</li><li><strong>印加</strong>的<strong>梯田农场</strong>获得0.5住房（1单位<strong>半住房</strong>）</li><li>住房机制调整：当人口大于等于住房数量时余粮归零 → 人口增长速度降低75%</li><li>删除旧版本遗留的<strong>美利坚</strong>的<strong>新政法案</strong>相关机制</li></ul><h2 id="v3-2-9-适配-4-19-9" tabindex="-1">v3.2.9 - 适配 4.19.9 <a class="header-anchor" href="#v3-2-9-适配-4-19-9" aria-label="Permalink to &quot;v3.2.9 - 适配 4.19.9&quot;">​</a></h2><h3 id="👑-调整二级政体" tabindex="-1">👑 调整<strong>二级政体</strong> <a class="header-anchor" href="#👑-调整二级政体" aria-label="Permalink to &quot;👑 调整**二级政体**&quot;">​</a></h3><ul><li><strong>古典共和</strong>：所有城市普及<strong>纪念碑</strong>时所有城市+1快乐 → 每个<strong>纪念碑</strong>+1快乐</li><li><strong>独裁统治</strong>：新增每个<strong>市政广场地标</strong>和<strong>外交区地标</strong>+1全产</li></ul><h3 id="🏛️-调整市政广场建筑" tabindex="-1">🏛️ 调整<strong>市政广场建筑</strong> <a class="header-anchor" href="#🏛️-调整市政广场建筑" aria-label="Permalink to &quot;🏛️ 调整**市政广场建筑**&quot;">​</a></h3><ul><li><strong>谒见厅</strong>：每个<strong>一级总督</strong>+2快乐+2粮 → +2快乐+3粮</li><li><strong>军阀宝库</strong>：所有城市+1锤 → 所有非占领城市训练军队时+25%锤且<strong>基本战略资源</strong>收集速度+25%</li></ul><h3 id="🌍-其他调整" tabindex="-1">🌍 其他调整 <a class="header-anchor" href="#🌍-其他调整" aria-label="Permalink to &quot;🌍 其他调整&quot;">​</a></h3><ul><li>允许<strong>建造者</strong>在解锁<strong>航海术</strong>后下海修建<strong>渔船</strong>（存疑，可能不生效）</li><li><strong>英吉利</strong>：<strong>黄金时代</strong>期间沿海城市+80%锤+100%金 → +20n%锤+25n%金（n为当前时代数，远古时代为1）</li><li><strong>印度尼西亚</strong>：删除 每个沿海城市+2快乐；删除 <strong>波罗勉宫</strong>的每个沿海城市+2信仰</li><li><strong>桑科雷大学</strong>：贸易站+1科+1金+1鸽 → +1科+2金+2鸽</li><li>修复总督<strong>瑞纳I</strong>不生效的错误及其衍生错误</li><li>新增<strong>支援加力</strong>机制：解锁<strong>军事传统</strong>后所有近战单位与友方单位相邻时防御敌方近战单位+10%力</li></ul><h2 id="v3-2-8-适配-4-19-9" tabindex="-1">v3.2.8 - 适配 4.19.9 <a class="header-anchor" href="#v3-2-8-适配-4-19-9" aria-label="Permalink to &quot;v3.2.8 - 适配 4.19.9&quot;">​</a></h2><ul><li>修复<strong>水渠</strong>区域无法修建的错误，解决方法是允许<strong>水渠</strong>区域随便放置</li><li>调整<strong>水渠</strong>区域相邻<strong>壶口瀑布</strong>时的加成：+4快乐 → +2快乐</li><li>调整<strong>马格努斯IIB</strong>总督技能：<strong>开拓者</strong>加速50% → 此城训练的<strong>开拓者</strong>不扣除人口且+1移动力</li><li>增强<strong>商业区域建筑</strong>： <ul><li><strong>银行</strong>+5金 → +10金</li><li><strong>大巴扎</strong>+7金 → +15金</li><li><strong>证券交易所</strong>+4金 → 10金</li><li><strong>证券交易所(通电)</strong>+7金 → +30金</li></ul></li></ul><h2 id="v3-2-7-适配-4-19-9" tabindex="-1">v3.2.7 - 适配 4.19.9 <a class="header-anchor" href="#v3-2-7-适配-4-19-9" aria-label="Permalink to &quot;v3.2.7 - 适配 4.19.9&quot;">​</a></h2><ul><li>修复砍伐<strong>森林</strong>和<strong>雨林</strong>的产出总是为最大值的错误</li><li>调整万神殿<strong>门神</strong>和<strong>狩猎女神</strong></li><li>修复<strong>商人</strong>不消耗<strong>商路容量</strong>的错误</li><li>调整<strong>古典共和</strong>和<strong>独裁统治</strong>政体</li><li>调整<strong>市政广场</strong>、<strong>学院</strong>和<strong>圣地</strong>区域贴图</li></ul><h2 id="v3-2-6-适配-4-19-9" tabindex="-1">v3.2.6 - 适配 4.19.9 <a class="header-anchor" href="#v3-2-6-适配-4-19-9" aria-label="Permalink to &quot;v3.2.6 - 适配 4.19.9&quot;">​</a></h2><ul><li>修复<strong>住房</strong>、<strong>区域位</strong>和<strong>商路容量</strong>不显示的错误</li></ul><h2 id="v3-2-5-适配-4-19-8" tabindex="-1">v3.2.5 - 适配 4.19.8 <a class="header-anchor" href="#v3-2-5-适配-4-19-8" aria-label="Permalink to &quot;v3.2.5 - 适配 4.19.8&quot;">​</a></h2><ul><li>新增<strong>开拓者</strong>和<strong>苏丹亲兵</strong>的掉人口机制</li><li>调整<strong>明朝</strong>技能</li><li>重大调整：允许<strong>区域</strong>和<strong>奇观</strong>修建在<strong>战略资源</strong>和<strong>奢侈品资源</strong>上，<strong>战略资源</strong>可以改良但<strong>奢侈品资源</strong>不可以</li></ul><h2 id="v3-2-4-适配-4-19-8" tabindex="-1">v3.2.4 - 适配 4.19.8 <a class="header-anchor" href="#v3-2-4-适配-4-19-8" aria-label="Permalink to &quot;v3.2.4 - 适配 4.19.8&quot;">​</a></h2><ul><li>河流刷新率上调：8倍 → 15倍</li><li>新增人口保底机制：首都获得3个2粮2锤<strong>专家</strong>岗位，其他城市获得1个</li><li>调整<strong>专家</strong>产出</li><li>修复更多锤子的<strong>建造者</strong>在耗尽次数后不消失的错误</li><li><strong>宫殿</strong>提供的快乐：+2 → +4</li><li><strong>奢侈品资源</strong>调整，基础提供4快乐，<strong>游戏和娱乐</strong>市政后额外+2</li></ul><h2 id="v3-2-3-适配-4-19-8" tabindex="-1">v3.2.3 - 适配 4.19.8 <a class="header-anchor" href="#v3-2-3-适配-4-19-8" aria-label="Permalink to &quot;v3.2.3 - 适配 4.19.8&quot;">​</a></h2><ul><li>新增更新日志在根目录</li><li>修改<strong>丹霞地貌</strong>贴图，更符合整体画风</li><li>重写<strong>元朝</strong>和<strong>秦朝</strong>的城市数量机制，优化性能</li></ul><h2 id="v3-2-2-适配-4-19-8" tabindex="-1">v3.2.2 - 适配 4.19.8 <a class="header-anchor" href="#v3-2-2-适配-4-19-8" aria-label="Permalink to &quot;v3.2.2 - 适配 4.19.8&quot;">​</a></h2><ul><li>修复<strong>城均快乐</strong>计算公式中城市数量在开局时作为0同时作为除数导致不能开局的错误</li></ul><h2 id="v3-2-1-适配-4-19-8" tabindex="-1">v3.2.1 - 适配 4.19.8 <a class="header-anchor" href="#v3-2-1-适配-4-19-8" aria-label="Permalink to &quot;v3.2.1 - 适配 4.19.8&quot;">​</a></h2><ul><li>重构宜居度系统，宜居度改名为<strong>城均快乐</strong>，并优化性能</li></ul><h2 id="v3-2-0" tabindex="-1">v3.2.0 <a class="header-anchor" href="#v3-2-0" aria-label="Permalink to &quot;v3.2.0&quot;">​</a></h2><p>时隔八个月复活！适配最新版 Unciv-4.19.7</p><h2 id="📚-更早版本" tabindex="-1">📚 更早版本 <a class="header-anchor" href="#📚-更早版本" aria-label="Permalink to &quot;📚 更早版本&quot;">​</a></h2><p>更早的版本更新日志请查看 <a href="https://github.com/AutumnPizazz/CoeHarMod" target="_blank" rel="noreferrer">GitHub 仓库</a>。</p>',117)])])}const b=r(l,[["render",i]]);export{c as __pageData,b as default};
